questions.prompt:
다음 C 언어로 구현된 프로그램을 분석하여 그 실행 결과를 쓰시오. (단, 출력문의 출력 서식을 준
    수하시오.) (5점)

     #include <stdio.h>
     #include <string.h>


     void inverse(char *str, int len) {
            for(int i = 0, j = len - 1; i < j; i++, j--) {
                    char ch = str[i];
                      str[i] = str[j];
                      str[j] = ch;
            }
     }

     int main() {
            char str[100] = "ABCDEFGH";
            int len = strlen(str);
            inverse(str, len);
            for(int i = 1; i < len; i += 2) {
                      printf("%c", str[i]);
            }
            return 0;
     }

promptBlocks.text:
#include <stdio.h>
#include <string.h>

void inverse(char *str, int len) {
    for(int i = 0, j = len - 1; i < j; i++, j--) {
        char ch = str[i];
        str[i] = str[j];
        str[j] = ch;
    }
}

int main() {
    char str[100] = "ABCDEFGH";
    int len = strlen(str);
    inverse(str, len);
    for(int i = 1; i < len; i += 2) {
        printf("%c", str[i]);
    }
    return 0;
}

