class Parent {
    int x, y;

    ① Parent(int x, int y) {
        this.x = x;
        this.y = y;
    }

    ② int getX() {
        return x*y;
    }
}

class Child extends Parent {
    int x;

    ③ Child(int x) {
        super(x+1, x);
        this.x = x;
    }

    ④ int getX(int n) {
        return super.getX() + n;
    }
